            CPhysicsMeshObject mesh_object = GetPhysicsTC()->GetPhysicsMeshObject();
            CMeshIntersectionData intersection;
            result = mesh_object.GetSphereIntersectionFromTo(radius, from, delta * 100.0f + from, intersection);
