        if (TimeOutCounter > 0) {
            CTCEntityEvents* events;
            if (GetCreature().GetTC(&events)) {
                NEntityEvents::CEventFiredShot* shot;
                while (events->GetEvent(&shot, NEntityEvents::CIsEventCreatedAfter(TimeOutCounter)))
